// Flatten multiple PDF files and generate S3 keys
return $input.all().flatMap(item => {
  const files = item.binary?.pdf_files || [];

  if (!files.length) {
    throw new Error("No binary files found in this item");
  }

  // If pdf_files is an array of binaries
  return files.map(file => {
    const safeName = file.filename
      .replace(/[^a-zA-Z0-9_.()-]/g, '_')
      .trim();

    const timestamp = $now.toFormat('yyyy-MM-dd-HHmmss');
    const s3Key = `uploads/${timestamp}/${safeName}`;

    return {
      json: {
        ...item.json,
        s3Key
      },
      binary: {
        pdf_files: file
      }
    };
  });
});
